(function(root){
 function extent(values){const numbers=values.filter(Number.isFinite);if(!numbers.length)return[0,100];let min=numbers.reduce((a,b)=>Math.min(a,b)),max=numbers.reduce((a,b)=>Math.max(a,b));const padding=max===min?Math.max(Math.abs(max)*.05,100):(max-min)*.08;return[min-padding,max+padding];}
 function scale(values,window=null,zero=false){let [min,max]=window||extent(values);if(zero&&!window)min=Math.min(0,min);if(!Number.isFinite(min)||!Number.isFinite(max)||max<=min)throw Error('纵轴上限必须大于下限。');const base=10**Math.floor(Math.log10((max-min)/4)),step=([1,2,2.5,5,10].find(n=>n>=(max-min)/4/base)||10)*base;if(!window){min=Math.floor(min/step)*step;max=Math.ceil(max/step)*step;if(values.every(v=>v===null||v>=0))min=Math.max(0,min);}const ticks=[];for(let v=Math.ceil(min/step)*step;v<=max+step*1e-8&&ticks.length<20;v+=step)ticks.push(v);return{min,max,step,ticks};}
 function zoom(bounds,factor){const center=(bounds.min+bounds.max)/2,span=Math.max(2,(bounds.max-bounds.min)*factor);return[center-span/2,center+span/2];}
 function memberColor(profile,index){return profile?.gender==='male'?'#168bd2':profile?.gender==='female'?'#df5987':['#279bb4','#df718e','#c28b2d','#56a16c','#7382d5'][Math.max(index,0)%5];}
 const yearPalette=['#6750d8','#e28024','#119a83','#d64d82','#288bc5','#9b62b5','#788b25','#b55735'];
 function yearColor(year){return'hsl('+(((Number(year)-2000)*137.508%360+360)%360).toFixed(2)+' 67% 48%)';}
 const api={extent,scale,zoom,memberColor,yearColor};if(typeof module!=='undefined'&&module.exports){module.exports=api;return;}root.FamilyChartAxis=api;
 api.attach=function(parent,label,onChange){let values=[],window=null,zero=false,bounds=scale([]);const panel=document.createElement('div');panel.className='y-axis-controls';panel.innerHTML='<div class="y-axis-buttons"><strong>纵轴 · 金额</strong></div><details><summary>设置纵轴金额范围</summary><div class="y-axis-range"><label>下限（元）<input type="number" step="0.01"></label><label>上限（元）<input type="number" step="0.01"></label><button type="button" class="outline">应用范围</button></div></details><p class="axis-status muted" role="status"></p>';const group=panel.querySelector('.y-axis-buttons'),[low,high]=panel.querySelectorAll('input');low.setAttribute('aria-label',label+'纵轴下限');high.setAttribute('aria-label',label+'纵轴上限');const status=panel.querySelector('.axis-status');
  function set(next,isZero=false){window=next;zero=isZero;status.textContent='';onChange();}
  for(const [name,fn]of [['纵轴放大',()=>set(zoom(bounds,.5))],['纵轴缩小',()=>set(zoom(bounds,2))],['自动适配',()=>set(null)],['从0开始',()=>set(null,true)]]){const b=document.createElement('button');b.type='button';b.className='outline';b.textContent=name;b.onclick=fn;group.append(b);}panel.querySelector('.y-axis-range button').onclick=()=>{const min=Number(low.value)*100,max=Number(high.value)*100;if(low.value===''||high.value===''||!Number.isFinite(min)||!Number.isFinite(max)||max<=min){status.textContent='请填写有效金额，上限须大于下限。';return;}set([min,max]);};parent.append(panel);
  return{scale(next){values=next;bounds=scale(values,window,zero);low.value=(bounds.min/100).toFixed(2);high.value=(bounds.max/100).toFixed(2);status.textContent=(window?'自定义范围':zero?'从0开始':'自动适配数据')+' · '+(bounds.min/100).toLocaleString('zh-CN',{maximumFractionDigits:2})+' — '+(bounds.max/100).toLocaleString('zh-CN',{maximumFractionDigits:2})+' 元；范围外数据仍保留。';return bounds;},reset(){window=null;zero=false;}};
 };
})(typeof globalThis!=='undefined'?globalThis:this);
